SELECT male_survival_with_diagnosis.has_dka, AVG(male_survival_with_diagnosis.dischtime - male_survival_with_diagnosis.admittime) AS average_length_of_stay, SUM(CASE WHEN male_survival_with_diagnosis.deathtime IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(male_survival_with_diagnosis.subject_id), 0) AS mortality_rate, SUM(CASE WHEN male_survival_with_diagnosis.subject_id IN (SELECT subject_id FROM procedures_icd WHERE icd_code LIKE '428.0%') THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(male_survival_with_diagnosis.subject_id), 0) AS procedure_rate, AVG(male_survival_with_diagnosis.edregtime - male_survival_with_diagnosis.admittime) AS average_registration_time, PERCENT_RANK() OVER (ORDER BY male_survival_with_diagnosis.has_dka) AS percentile_rank FROM male_survival_with_diagnosis GROUP BY male_survival_with_diagnosis.has_dka ORDER BY male_survival_with_diagnosis.has_dka NULLS LAST;